const {extract}=require('./sourceExtractionDiagnostic'),historical=require('./pricingDirectiveGroupsActualJudge');
const INPUT='tests/release-inputs/source-extraction18-inputs-2026-09-27.json',PIN='fee5792544c18382e05cda6d5d5499830075452194fb494a322c7e96a9d9508e';
const sha=x=>createHash('sha256').update(x).digest('hex');
function completeWire(raw){let frames;try{frames=[JSON.parse(raw)];}catch{frames=raw.trim().split('\n').map(line=>JSON.parse(line));}assert.equal(frames.at(-1)?.done_reason,'stop');return historical.reconstruct(raw);}
