function packets(root){const bytes=fs.readFileSync(path.join(root,INPUT));assert.equal(sha(bytes),PIN);const rows=JSON.parse(bytes).packets;assert.deepEqual(rows.map(x=>x.id),Array.from({length:18},(_,i)=>'SE'+String(i+1).padStart(2,'0')));return rows;}
function strictTransport(options){const wire=historical.transport(options),seen=new Set();let active=null,metadata=0;return {calls:wire.calls,close:()=>wire.close(),beginCase(id){assert(/^SE(?:0[1-9]|1[0-8])$/.test(id));assert(!seen.has(id));wire.beginCase(id);active=id;},endCase(){wire.endCase();active=null;},fetch(url,opts){assert(wire.calls.length<19);const pathname=new URL(url).pathname;if(pathname==='/api/chat'){assert(active&&!seen.has(active));seen.add(active);}else{assert.equal(pathname,'/api/tags');assert.equal(++metadata,1);assert.equal(active,null);}return wire.fetch(url,opts);}};}
async function cohort(rows,{invoke,signal,record=()=>{}}){assert.deepEqual(rows.map(x=>x.id),Array.from({length:18},(_,i)=>'SE'+String(i+1).padStart(2,'0')));const state={status:'running',technicalComplete:false,creditAuthorized:false,semanticAccepted:null,cases:[],unattempted:rows.map(x=>x.id)};try{for(const item of rows){signal?.throwIfAborted();const row={id:item.id,result:null};state.cases.push(row);state.unattempted.shift();record(state);row.result=await extract({source:item.source},(request,options)=>invoke(item.id,request,options),{signal,timeoutMs:60000});record(state);}state.technicalComplete=state.cases.length===18&&state.cases.every(x=>x.result.calls===1&&['EXTRACTION_OBSERVED','INVALID_OUTPUT'].includes(x.result.reason));state.status=state.technicalComplete?'predictions-complete':'predictions-incomplete';}catch{state.status='predictions-incomplete';}record(state);return state;}
async function main(){assert.equal(process.env.SOURCE_EXTRACTION_ACTUAL,'1');const output=process.env.SOURCE_EXTRACTION_RESULT;assert(path.isAbsolute(output));const control=new AbortController(),timer=setTimeout(()=>control.abort(),1110000),original=global.fetch;let wire;const state={status:'preparing',inputSha256:PIN,model:{name:historical.MODEL,digest:historical.DIGEST},scope:'18 synthetic source-only extractions; no actor, effects or credit',bounds:{inference:18,metadata:1,allHttp:19,callSeconds:60},cases:[],calls:[]};const save=()=>{fs.writeFileSync(output+'.tmp',JSON.stringify(state,null,2)+'\n',{mode:0o600});fs.renameSync(output+'.tmp',output);};try{wire=strictTransport({fetch:original,signal:control.signal,record:()=>{state.calls=wire.calls;save();}});global.fetch=wire.fetch;const tags=await fetch('http://127.0.0.1:11434/api/tags');assert.equal(tags.status,200);assert.equal((await tags.json()).models.find(x=>x.name===historical.MODEL)?.digest,historical.DIGEST);const model=require('../../server/agent-runtime/providers/langchainProvider').createLangChainProvider({provider:'ollama',baseURL:'http://127.0.0.1:11434',model:historical.MODEL});Object.assign(state,await cohort(packets(process.cwd()),{signal:control.signal,record:partial=>{Object.assign(state,partial);save();},invoke:async(id,request,options)=>{wire.beginCase(id);try{const value=await model.chat(request.messages,[],{temperature:0,max_tokens:4096,num_predict:4096,num_ctx:16384,timeout:options.timeoutMs,signal:options.signal,format:request.schema});assert.equal(value.provider,'ollama');assert.equal(value.model,historical.MODEL);assert(!value.mocked&&!value.fallback);const sent=wire.calls.filter(x=>x.caseId===id);assert.equal(sent.length,1);assert.equal(sent[0].status,'returned');assert.equal(sent[0].httpStatus,200);assert.deepEqual(JSON.parse(sent[0].request).messages,request.messages);assert.deepEqual(JSON.parse(sent[0].request).format,request.schema);assertWireOptions(JSON.parse(sent[0].request));assert.equal(completeWire(sent[0].response),value.response);return value.response;}finally{wire.endCase();}}}));}catch{state.status='predictions-incomplete';state.technicalComplete=false;}finally{clearTimeout(timer);control.abort();wire?.close();global.fetch=original;save();}if(!state.technicalComplete)process.exitCode=1;}
module.exports={completeWire,assertWireOptions,packets,strictTransport,cohort,INPUT,PIN};if(require.main===module)main().catch(()=>{console.error('Source extraction diagnostic unavailable');process.exitCode=1;});
